<!DOCTYPE html><html><head><meta charset="utf-8"><style>@page{margin:28px}body{font-family:DejaVu Sans,sans-serif;color:#17212a;font-size:10px}h1{margin:0;font-size:24px}.brand{color:#b67d24;font-weight:bold;letter-spacing:2px}.meta{color:#68747d;margin:6px 0 22px}table{width:100%;border-collapse:collapse}th{background:#111820;color:#fff;text-align:left;padding:9px 7px;font-size:9px}td{border-bottom:1px solid #dfe4e8;padding:9px 7px;vertical-align:top}.muted{color:#68747d;font-size:9px}.status{font-weight:bold;text-transform:capitalize}.footer{position:fixed;bottom:-12px;left:0;right:0;color:#89939a;font-size:8px;text-align:right}</style></head><body><div class="brand">PROFLECT</div><h1>Claims Report</h1><div class="meta">Generated {{ now()->format('d M Y, h:i A') }} | {{ $claims->count() }} records</div><table><thead><tr><th>Claim ID</th><th>Warranty Code</th><th>Customer</th><th>Vehicle</th><th>Plan</th><th>Panels</th><th>Submitted</th><th>Status</th></tr></thead><tbody>@forelse($claims as $claim)<tr><td>{{ $claim->claim_number }}</td><td>{{ $claim->warrantyCode?->code ?: '—' }}</td><td>{{ $claim->user->name }}<br><span class="muted">{{ $claim->user->email }}</span></td><td>{{ trim($claim->vehicle_make.' '.$claim->vehicle_model) ?: 'Not provided' }}<br><span class="muted">{{ $claim->registration_number ?: '—' }}{{ $claim->vehicle_year ? ' · '.$claim->vehicle_year : '' }}</span></td><td>{{ $claim->subscription->plan->name }}</td><td>{{ collect($claim->panels)->map(fn($panel)=>collect($claim->panel_details ?? [])->firstWhere('key',$panel)['name'] ?? \App\Models\Claim::PANELS[$panel] ?? $panel)->join(', ') }}</td><td>{{ $claim->created_at->format('d M Y') }}</td><td class="status">{{ $claim->status }}</td></tr>@empty<tr><td colspan="8">No claims found.</td></tr>@endforelse</tbody></table><div class="footer">Proflect Claims Report</div></body></html>
